def compute(vars):
    previous = vars["v1"]
    current = vars["v2"]

    if previous == 0:
        return None

    decrease = previous - current
    change_ratio = decrease / previous
    percentage_decrease = change_ratio * 100

    return {
        "value": percentage_decrease,
        "trace": {
            "previous_value": previous,
            "current_value": current,
            "decrease": decrease,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
